-- -----------------------------------
-- Table structure for `unique_atm_codes`
-- -----------------------------------

DROP TABLE IF EXISTS `unique_atm_codes`;
CREATE TABLE `unique_atm_codes` (
  `id` int(6) NOT NULL AUTO_INCREMENT,
  `atmid` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unique_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` tinyint(1) DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7056 DEFAULT CHARSET=latin1;

